if(root.dataset.readOnly==='1'){root.querySelectorAll('[data-wf-form] input').forEach(input=>{input.disabled=true;input.setAttribute('aria-disabled','true')});const reset=root.querySelector('[data-wf-reset]');if(reset)reset.hidden=true;const note=root.querySelector('.wf-assumption-note');if(note)note.textContent='Project assumptions are shown for reference and cannot be changed by this account.'}
function formatCurrencyInputs(){root.querySelectorAll('input[data-unit="$"]:not([readonly])').forEach(el=>el.value=money2.format(n(el.name)))}
function setAssumptionsCollapsed(collapsed){root.classList.toggle('wf-assumptions-collapsed',collapsed);const button=root.querySelector('[data-wf-assumption-toggle]');if(!button)return;button.setAttribute('aria-expanded',String(!collapsed));button.querySelector('span').textContent=collapsed?'›':'‹';button.querySelector('b').textContent=collapsed?'Show Assumptions':'Collapse';try{localStorage.setItem('znp-model-assumptions-collapsed',collapsed?'1':'0')}catch(error){}}
let assumptionsCollapsed=false;try{assumptionsCollapsed=localStorage.getItem('znp-model-assumptions-collapsed')==='1'}catch(error){}setAssumptionsCollapsed(assumptionsCollapsed);
root.addEventListener('click',e=>{if(e.target.closest('[data-export-monthly-cash]')){exportMonthlyCashFlow();return}const assumptionToggle=e.target.closest('[data-wf-assumption-toggle]');if(assumptionToggle){setAssumptionsCollapsed(!root.classList.contains('wf-assumptions-collapsed'));return}const button=e.target.closest('[data-year-detail]');if(!button)return;const detail=root.querySelector('[data-year-detail-row="'+button.dataset.yearDetail+'"]'),open=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!open));button.textContent=(open?'▸ ':'▾ ')+'Year '+button.dataset.yearDetail;if(detail)detail.hidden=open});
root.addEventListener('focusin',e=>{if(e.target.matches('input[data-unit="$"]:not([readonly])'))e.target.value=n(e.target.name).toFixed(2)});root.addEventListener('focusout',e=>{if(e.target.matches('input[data-unit="$"]:not([readonly])'))e.target.value=money2.format(n(e.target.name))});root.addEventListener('input',e=>{if(!e.target.matches('input'))return;const pairs={lpSplit:'gpSplit',gpSplit:'lpSplit',tier2LpSplit:'tier2GpSplit',tier2GpSplit:'tier2LpSplit'},partner=root.querySelector('[name="'+(pairs[e.target.name]||'')+'"]');if(partner)partner.value=Math.max(0,100-Math.min(100,n(e.target.name))).toFixed(2);render()});root.querySelector('[data-wf-reset]').addEventListener('click',()=>{Object.entries(defaults).forEach(([k,v])=>{const el=root.querySelector('[name="'+k+'"]');if(el)el.value=v});render();formatCurrencyInputs()});render();
